import { Image, ScrollView, Text, View } from 'react-native';

export function HikeSummary({ hike }) {
  return (
    <ScrollView contentContainerStyle={{ padding: 16, gap: 12 }}>
      <Image
        source={{ uri: hike.photoUrl }}
        style={{ width: '100%', height: 200 }}
      />
      <Text style={{ fontSize: 24, fontWeight: '700' }}>{hike.name}</Text>
      <View style={{ flexDirection: 'row', gap: 12 }}>
        <Text>{hike.distanceKm} km</Text>
        {hike.elevationM} m up
      </View>
      {hike.photoCount && <Text>{hike.photoCount} photos</Text>}
      <Text numberOfLines={3}>{hike.notes}</Text>
    </ScrollView>
  );
}
